record ProductDtoV1(long id, String name, double price) {}

// Dodanie category jest ZMIANA KOMPATYBILNA - stary klient dalej odczyta id/name/price
record ProductDtoV1WithOptionalField(long id, String name, double price, String category) {}

// Klient parsujacy TYLKO znane sobie pola - nowe pole warrantyMonths jest CELOWO ignorowane
record KnownProductFields(long id, String name, double price) {}

KnownProductFields parseKnownFieldsOnly(Map<String, Object> rawJson) {
    return new KnownProductFields(
        ((Number) rawJson.get("id")).longValue(),
        (String) rawJson.get("name"),
        ((Number) rawJson.get("price")).doubleValue()
    ); // rawJson moze zawierac "warrantyMonths" - parser go po prostu nie czyta
}

// V1, juz uzywana przez klientow:
record ProductDtoBefore(long id, String name, double price) {}

// ZLE: zmiana typu price w TEJ SAMEJ wersji - kazdy dotychczasowy klient parsujacy
// "price" jako liczbe dostanie teraz String i sie wysypie
record ProductDtoAfterBreaking(long id, String name, String price) {}

// DOBRZE: V1 zostaje bez zmian, V2 wprowadza nowy typ jawnie, pod nowa sciezka
record ProductDtoV1(long id, String name, double price) {}
record ProductDtoV2(long id, String name, String priceFormatted) {} // np. "29.99 PLN"

// Obie wersje mapowane z tego samego ProductEntity, kazda wlasnym mapperem
ProductDtoV1 mapToV1(ProductEntity entity) {
    return new ProductDtoV1(entity.id(), entity.name(), entity.price());
}
ProductDtoV2 mapToV2(ProductEntity entity) {
    return new ProductDtoV2(entity.id(), entity.name(), entity.price() + " PLN");
}
